import{_ as t,o,c as n,ag as d}from"./chunks/framework.BZohXCq9.js";const g=JSON.parse('{"title":"Phase 1: Admin Dashboard – Complete Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"01_ADMIN_DASHBOARD.md","filePath":"01_ADMIN_DASHBOARD.md"}'),s={name:"01_ADMIN_DASHBOARD.md"};function r(a,e,i,c,l,u){return o(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="phase-1-admin-dashboard-–-complete-documentation" tabindex="-1">Phase 1: Admin Dashboard – Complete Documentation <a class="header-anchor" href="#phase-1-admin-dashboard-–-complete-documentation" aria-label="Permalink to &quot;Phase 1: Admin Dashboard – Complete Documentation&quot;">​</a></h1><p>This document describes <strong>everything</strong> that happens in the Admin Dashboard: routes, layout, each screen, which frontend components and GraphQL operations are used, and which backend resolvers and types are involved. Use it to onboard new developers or to trace a feature from UI to database.</p><hr><h2 id="_1-purpose-and-entry-point" tabindex="-1">1. Purpose and entry point <a class="header-anchor" href="#_1-purpose-and-entry-point" aria-label="Permalink to &quot;1. Purpose and entry point&quot;">​</a></h2><ul><li><strong>Purpose:</strong> Admins manage the platform: view analytics, manage signup links, instructors, students, bookings, documents, transactions, refund requests, and (for super admins) FAQ/contact details.</li><li><strong>Entry:</strong> User signs in with an account that has <code>role: &quot;Admin&quot;</code>. After sign-in, the app redirects to <code>/admin-dashboard/overview</code>.</li><li><strong>Protection:</strong> All <code>/admin-dashboard/*</code> routes are wrapped in <code>AdminPrivateRoute</code>, which checks auth and role; unauthenticated or non-admin users are redirected (e.g. to sign-in or overview).</li></ul><hr><h2 id="_2-layout-and-routing" tabindex="-1">2. Layout and routing <a class="header-anchor" href="#_2-layout-and-routing" aria-label="Permalink to &quot;2. Layout and routing&quot;">​</a></h2><h3 id="_2-1-how-the-admin-area-is-mounted" tabindex="-1">2.1 How the admin area is mounted <a class="header-anchor" href="#_2-1-how-the-admin-area-is-mounted" aria-label="Permalink to &quot;2.1 How the admin area is mounted&quot;">​</a></h3><ul><li><strong>Route definition:</strong> <code>Frontend/src/routes/index.tsx</code><ul><li>Path: <code>/admin-dashboard</code></li><li>Element: <code>AdminRoutes</code> (which wraps children in <code>AdminLayout</code> and <code>AdminPrivateRoute</code>).</li></ul></li><li><strong>Layout:</strong> <code>Frontend/src/layouts/AdminLayout.tsx</code><ul><li>Renders: sidebar (<code>Sidebar</code>), top bar (<code>Navbar</code>), and <code>children</code> (the current page).</li><li>Sidebar menu items (overview, admin access, documents, instructor/student/booking management, transactions, refund requests, help &amp; support for super admin) are defined in <code>AdminLayout</code>.</li><li>Uses <code>useBookingNotifications</code> and <code>initSocket</code> for real-time booking notification badge on &quot;Booking Management&quot;.</li></ul></li><li><strong>Route guard:</strong> <code>Frontend/src/routes/AdminRoutes.tsx</code> uses <code>AdminPrivateRoute</code> from <code>Frontend/src/components/PrivateRoute</code> (or equivalent) to ensure only authenticated admins can see the dashboard.</li></ul><h3 id="_2-2-sidebar-menu-from-adminlayout" tabindex="-1">2.2 Sidebar menu (from AdminLayout) <a class="header-anchor" href="#_2-2-sidebar-menu-from-adminlayout" aria-label="Permalink to &quot;2.2 Sidebar menu (from AdminLayout)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th></tr></thead><tbody><tr><td>Overview</td><td><code>/admin-dashboard/overview</code></td></tr><tr><td>Admin Access</td><td><code>/admin-dashboard/admin-access</code></td></tr><tr><td>Documents</td><td><code>/admin-dashboard/documentsManagement</code></td></tr><tr><td>Instructor Management</td><td><code>/admin-dashboard/InstructorManagement</code></td></tr><tr><td>Booking Management</td><td><code>/admin-dashboard/bookingManagement</code></td></tr><tr><td>Student Management</td><td><code>/admin-dashboard/StudentManagement</code></td></tr><tr><td>Payment management</td><td><code>/admin-dashboard/transactions</code></td></tr><tr><td>Refund requests</td><td><code>/admin-dashboard/refund-requests</code></td></tr><tr><td>Help &amp; Support</td><td><code>/admin-dashboard/help-support</code> (super admin only)</td></tr><tr><td>Logout</td><td><code>/logout</code> (handled in layout)</td></tr></tbody></table><hr><h2 id="_3-screen-by-screen-breakdown" tabindex="-1">3. Screen-by-screen breakdown <a class="header-anchor" href="#_3-screen-by-screen-breakdown" aria-label="Permalink to &quot;3. Screen-by-screen breakdown&quot;">​</a></h2><p>For each screen we list: <strong>route</strong>, <strong>component(s)</strong>, <strong>what it does</strong>, <strong>GraphQL operations</strong>, <strong>backend (resolvers / typeDefs)</strong>, and <strong>main files</strong>.</p><hr><h3 id="_3-1-overview-analytics" tabindex="-1">3.1 Overview (Analytics) <a class="header-anchor" href="#_3-1-overview-analytics" aria-label="Permalink to &quot;3.1 Overview (Analytics)&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/overview</code></li><li><strong>Component:</strong> <code>AnalyticsDashboard</code> is the default export of <code>Frontend/src/pages/private/admin-dashboard/adminOverview.tsx</code>. The same file also exports <code>AdminOverview</code>; the router uses <code>AnalyticsDashboard</code> for this route.</li><li><strong>What it does:</strong> Shows admin analytics: overall stats (registrations, lessons booked, reviews, attendance), and graphs (active users, revenue per instructor, bookings per instructor, total earnings, conversion rates). Supports filters (date range, instructor).</li><li><strong>Frontend – GraphQL:</strong><ul><li><code>GET_ADMIN_ANALYTICS</code> (with variable <code>filter: AnalyticsFilterInput</code>) – used by the main analytics view.</li><li><code>GET_ALL_INSTRUCTORS</code> – used for instructor filter dropdown (id, firstName, lastName).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/admin-dashboard/adminOverview.tsx</code></li><li><code>Frontend/src/graphql/Queries/AdminContact.ts</code> (defines <code>GET_ADMIN_ANALYTICS</code>, <code>GET_ALL_INSTRUCTORS</code>)</li><li><code>Frontend/src/types/AdminContact.ts</code> (types for analytics and filter)</li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> <code>server/src/graphql/resolvers/AdminAnalytics.resolver.js</code> – <code>getAdminAnalytics</code>, <code>getAllInstructors</code> (the analytics <code>getAllInstructors</code> here may be the same as or merged with the one in main resolvers; the typeDefs live in AdminOverallAnalyticsTypes).</li><li><strong>TypeDefs:</strong> <code>server/src/graphql/typeDefs/AdminOverallAnalyticsTypes.js</code> – <code>AnalyticsFilterInput</code>, <code>AdminAnalytics</code>, <code>OverallStats</code>, <code>GraphData</code>, and related types; <code>Query.getAdminAnalytics(filter)</code>, <code>Query.getAllInstructors</code>.</li></ul></li><li><strong>Data flow:</strong> User selects filter → frontend sends <code>GET_ADMIN_ANALYTICS</code> with <code>filter</code> → backend computes date range and optional instructor filter, aggregates from <code>User</code>, <code>studentBookingModel</code>, <code>Review</code>, <code>Visitor</code> → returns stats and graph data → UI renders charts (e.g. ApexCharts) and summary cards.</li></ul><hr><h3 id="_3-2-admin-access-signup-links" tabindex="-1">3.2 Admin Access (Signup links) <a class="header-anchor" href="#_3-2-admin-access-signup-links" aria-label="Permalink to &quot;3.2 Admin Access (Signup links)&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/admin-access</code></li><li><strong>Component:</strong> <code>AdminAccess</code> in <code>Frontend/src/pages/private/admin-dashboard/AdminAccess.tsx</code>.</li><li><strong>What it does:</strong> Lists all signup links; create new link (firstName, lastName, email, agreement); copy link; delete link.</li><li><strong>Frontend – GraphQL:</strong><ul><li>Query: <code>GET_ALL_SIGNUP_LINKS</code> – returns id, firstName, lastName, email, token, signupDate, pending, signupLink.</li><li>Mutations: <code>CREATE_SIGNUP_LINK</code> (firstName, lastName, email), <code>DELETE_SIGNUP_LINK</code> (id).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/admin-dashboard/AdminAccess.tsx</code></li><li><code>Frontend/src/graphql/mutations/auth.ts</code> (defines <code>GET_ALL_SIGNUP_LINKS</code>, <code>CREATE_SIGNUP_LINK</code>, <code>DELETE_SIGNUP_LINK</code>; note the create mutation may be named <code>CREATE_SIGNUP_LINK</code> or similar and call <code>createSignUpLink</code> on the backend).</li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> <code>server/src/graphql/SignupLink/SignupLinkResolver.js</code> – <code>getAllSignupLinks</code>, <code>createSignUpLink</code>, <code>deleteSignUpLink</code>.</li><li><strong>TypeDefs:</strong> <code>server/src/graphql/SignupLink/SignupLinkTypedef.js</code> – <code>SignupLink</code> type, <code>Query.getAllSignupLinks</code>, <code>Mutation.createSignUpLink</code>, <code>Mutation.deleteSignUpLink</code>.</li></ul></li><li><strong>Data flow:</strong> Page load → <code>GET_ALL_SIGNUP_LINKS</code> → list of links. Create form submit → <code>CREATE_SIGNUP_LINK</code> → new link appears after refetch. Delete → <code>DELETE_SIGNUP_LINK</code> → list refetches.</li></ul><hr><h3 id="_3-3-documents-management" tabindex="-1">3.3 Documents management <a class="header-anchor" href="#_3-3-documents-management" aria-label="Permalink to &quot;3.3 Documents management&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/documentsManagement</code></li><li><strong>Component:</strong> <code>InstructorDocumentsTable</code> from <code>Frontend/src/components/AdminComponents/InstructorDocumentsTable.tsx</code>.</li><li><strong>What it does:</strong> Table of all instructors and their documents (e.g. Swiss Driving License, other doc types). Supports search and filters (status, instructor). Clicking a row navigates to document details.</li><li><strong>Detail route:</strong> <code>/admin-dashboard/document-details/:instructorId/:documentType</code></li><li><strong>Detail component:</strong> <code>DocumentDetailsPage</code> in <code>Frontend/src/pages/private/admin-dashboard/DocumentsDetailPage.tsx</code> – shows one instructor’s documents of a given type; uses <code>GET_ALL_INSTRUCTORS</code> and then finds the instructor and document set on the client (or a dedicated query if added).</li><li><strong>Frontend – GraphQL:</strong><ul><li><code>GET_ALL_INSTRUCTORS</code> from <code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code> – query name <code>GetAllInstructors</code>, field <code>allInstructors</code> with <code>documents</code> (documentType, documentUrl, status, etc.). Used by <code>InstructorDocumentsTable</code>. Documents detail page may use the same or a single-instructor query.</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/components/AdminComponents/InstructorDocumentsTable.tsx</code></li><li><code>Frontend/src/pages/private/admin-dashboard/DocumentsDetailPage.tsx</code></li><li><code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code></li><li><code>Frontend/src/types/Instructor.ts</code> (e.g. <code>FlattenedDocument</code>)</li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> <code>allInstructors</code> is implemented in <code>server/src/graphql/resolvers.js</code> (main resolvers), returning instructors with their <code>documents</code> from the Instructor model.</li><li><strong>TypeDefs:</strong> Instructor type with <code>documents</code> is in the main <code>server/src/graphql/typeDefs.js</code> (or merged from a module). Document status updates may use a separate mutation (e.g. update document status) if present in the UI.</li></ul></li><li><strong>Data flow:</strong> Load table → <code>allInstructors</code> with documents → frontend flattens to one row per document (or per document group for Swiss License) and applies search/filters. Navigate to detail → same or single-instructor data → show document list and status; any status change would call the corresponding mutation.</li></ul><hr><h3 id="_3-4-instructor-management" tabindex="-1">3.4 Instructor management <a class="header-anchor" href="#_3-4-instructor-management" aria-label="Permalink to &quot;3.4 Instructor management&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/InstructorManagement</code></li><li><strong>Component:</strong> <code>InstructorManagement</code> in <code>Frontend/src/pages/private/admin-dashboard/InstructorManagement.tsx</code>. Uses <code>FilterPopover</code>, <code>InstructorCard</code>, <code>InstructorDetailModal</code>, <code>DeleteConfirmationModal</code> from <code>Frontend/src/components/AdminComponents/</code>.</li><li><strong>What it does:</strong> Lists all instructors with details (card view). Filter by gender, verification, experience, date range. Select instructors and delete (bulk). Open detail modal per instructor.</li><li><strong>Frontend – GraphQL:</strong><ul><li>Query: <code>GET_ALL_INSTRUCTORS_DETAILS</code> – field <code>allInstructorsWithDetails</code> (full instructor profile + lessonPrice, studentCount, reviewRating, documents, etc.).</li><li>Mutation: <code>DELETE_INSTRUCTORS</code> (variable <code>instructorIds: [ID!]!</code>).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/admin-dashboard/InstructorManagement.tsx</code></li><li><code>Frontend/src/graphql/Queries/InstructorProfiles.ts</code> (<code>GET_ALL_INSTRUCTORS_DETAILS</code>, <code>DELETE_INSTRUCTORS</code>)</li><li><code>Frontend/src/types/Instructor.ts</code></li><li><code>Frontend/src/components/AdminComponents/FilterPopOver.tsx</code>, <code>InstructorCard.tsx</code>, <code>InstructorDetailModal.tsx</code>, <code>DeleteConfirmation.tsx</code></li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> In <code>server/src/graphql/resolvers.js</code>: <code>allInstructorsWithDetails</code>, <code>deleteInstructors</code> (or similar name).</li><li><strong>TypeDefs:</strong> In main <code>server/src/graphql/typeDefs.js</code>: <code>InstructorWithDetails</code> (or equivalent), <code>Query.allInstructorsWithDetails</code>, <code>Mutation.deleteInstructors</code>.</li></ul></li><li><strong>Data flow:</strong> Load → <code>allInstructorsWithDetails</code> → display cards; filters applied in frontend. Delete → <code>deleteInstructors(instructorIds)</code> → refetch or update cache.</li></ul><hr><h3 id="_3-5-booking-management" tabindex="-1">3.5 Booking management <a class="header-anchor" href="#_3-5-booking-management" aria-label="Permalink to &quot;3.5 Booking management&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/bookingManagement</code></li><li><strong>Component:</strong> <code>StudentBookingTable</code> from <code>Frontend/src/components/AdminComponents/StudentBookingTable.tsx</code> (not from the page file that exports the same name in <code>admin-dashboard</code>; the router imports the component from <code>AdminComponents</code>).</li><li><strong>What it does:</strong> Table of all student bookings (all slots across all bookings). Admin can change slot status (e.g. available, booked, completed, refund, cancelled, missed) and cancel a booking. Badge on sidebar shows count of new/unseen bookings when using socket notifications.</li><li><strong>Frontend – GraphQL:</strong><ul><li>Query: <code>GET_ALL_STUDENT_BOOKINGS</code> – returns all bookings with student, instructor, slots (id, date, startTime, endTime, status, etc.), totalAmount, finalAmount, paymentMethod, status.</li><li>Mutations: <code>UPDATE_BOOKING_STATUS</code> (update a slot’s status), <code>CANCEL_BOOKING_ADMIN</code> (cancel a booking/slot as admin).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/components/AdminComponents/StudentBookingTable.tsx</code></li><li><code>Frontend/src/graphql/Queries/AdminBookingShowcase.ts</code> (<code>GET_ALL_STUDENT_BOOKINGS</code>)</li><li><code>Frontend/src/graphql/mutations/AdminBookingsShowcase.ts</code> (<code>UPDATE_BOOKING_STATUS</code>, <code>CANCEL_BOOKING_ADMIN</code>)</li><li><code>Frontend/src/types/AdminBookingShowcase.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> <code>server/src/graphql/resolvers/AdminBookingType.resolver.js</code> – <code>getAllStudentBookings</code>, and mutations for updating slot status and cancelling booking (names aligned with schema).</li><li><strong>TypeDefs:</strong> <code>server/src/graphql/typeDefs/AdminBookingType.js</code> – <code>StudentBookingAdmin</code>, <code>BookingSlotAdmin</code>, slot status enum, <code>Query.getAllStudentBookings</code>, and the admin booking mutations.</li></ul></li><li><strong>Data flow:</strong> Load → <code>getAllStudentBookings</code> → table of bookings/slots. Change status → <code>updateBookingStatus</code> (or equivalent) with bookingId/slotId/status. Cancel → <code>cancelBookingAdmin</code> (or equivalent). Refetch or cache update after mutations.</li></ul><hr><h3 id="_3-6-student-management" tabindex="-1">3.6 Student management <a class="header-anchor" href="#_3-6-student-management" aria-label="Permalink to &quot;3.6 Student management&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/StudentManagement</code></li><li><strong>Component:</strong> <code>StudentManagement</code> in <code>Frontend/src/pages/private/admin-dashboard/StudentManagement.tsx</code>. Uses <code>StudentFilterPopover</code>, <code>StudentCard</code>, <code>StudentDetailModal</code>, <code>StudentDeleteConfirmationModal</code>.</li><li><strong>What it does:</strong> Lists all students with lesson stats. Filter by verification, lesson count, location. Select students and delete (bulk). Open detail modal per student.</li><li><strong>Frontend – GraphQL:</strong><ul><li>Query: <code>GET_ALL_STUDENTS_ADMIN</code> – field <code>allStudentsWithLessonStats</code> (student list with lesson-related stats).</li><li>Mutation: <code>DELETE_STUDENTS</code> (variable <code>studentIds: [ID!]!</code> or similar).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/admin-dashboard/StudentManagement.tsx</code></li><li><code>Frontend/src/graphql/Queries/StudentQueries.ts</code> (<code>GET_ALL_STUDENTS_ADMIN</code>, <code>DELETE_STUDENTS</code>)</li><li><code>Frontend/src/types/Student.ts</code></li><li><code>Frontend/src/components/AdminComponents/StudentFilterPopover.tsx</code>, <code>StudentCard.tsx</code>, <code>StudentDetailModel.tsx</code>, <code>StudentDeleteConfirmationModal.tsx</code></li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> In <code>server/src/graphql/resolvers.js</code> (or a student resolver file): <code>allStudentsWithLessonStats</code>, <code>deleteStudents</code>.</li><li><strong>TypeDefs:</strong> In main typeDefs: <code>Query.allStudentsWithLessonStats</code>, <code>Mutation.deleteStudents</code>.</li></ul></li><li><strong>Data flow:</strong> Load → <code>allStudentsWithLessonStats</code> → cards; filters in frontend. Delete → <code>deleteStudents(studentIds)</code> → refetch.</li></ul><hr><h3 id="_3-7-payment-management-transactions" tabindex="-1">3.7 Payment management (Transactions) <a class="header-anchor" href="#_3-7-payment-management-transactions" aria-label="Permalink to &quot;3.7 Payment management (Transactions)&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/transactions</code></li><li><strong>Component:</strong> <code>AdminTransactionsPage</code> in <code>Frontend/src/pages/private/admin-dashboard/AdminTransactionsPage.tsx</code>.</li><li><strong>What it does:</strong> Lists all transactions with pagination. Filter by “party” (All / Admin / Instructor / Student) and by type (All / Payments / Refunds / Payouts / Reversals / Adjustments). Shows stats (e.g. total amounts). Can open commission settings (view/edit platform commission). Table columns include ref number, date, lesson slot (date/time), type, description, amount, status; “View” opens a details modal.</li><li><strong>Frontend – GraphQL:</strong><ul><li>Queries: <code>GET_ADMIN_TRANSACTIONS_WITH_PARTIES</code> (or the paginated <code>GET_ADMIN_TRANSACTIONS</code> with limit/offset and filter), <code>GET_ADMIN_TRANSACTIONS_COUNT</code>, <code>GET_ADMIN_TRANSACTION_STATS</code>. Optionally <code>GET_PLATFORM_COMMISSION_SETTINGS</code>.</li><li>Mutation: <code>UPDATE_PLATFORM_COMMISSION_SETTINGS</code> (when editing commission).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/admin-dashboard/AdminTransactionsPage.tsx</code></li><li><code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> <code>server/src/graphql/resolvers/transaction.resolver.js</code> – <code>getAdminTransactions</code>, <code>getAdminTransactionCount</code>, <code>getAdminTransactionStats</code>, and commission-related queries/mutations if they live here or in another resolver.</li><li><strong>TypeDefs:</strong> <code>server/src/graphql/typeDefs/transaction.typeDefs.js</code> – Transaction type, filters, <code>Query.getAdminTransactions(limit, offset, filter)</code>, <code>Query.getAdminTransactionCount(filter)</code>, <code>Query.getAdminTransactionStats</code>, and platform commission types/mutations.</li></ul></li><li><strong>Data flow:</strong> Load → fetch transactions (paginated) + count + stats with current filter. Changing tab (party/type) or page → new variables → refetch. Commission form → <code>UPDATE_PLATFORM_COMMISSION_SETTINGS</code> mutation.</li></ul><hr><h3 id="_3-8-refund-requests" tabindex="-1">3.8 Refund requests <a class="header-anchor" href="#_3-8-refund-requests" aria-label="Permalink to &quot;3.8 Refund requests&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/refund-requests</code></li><li><strong>Component:</strong> <code>AdminRefundRequestsPage</code> in <code>Frontend/src/pages/private/admin-dashboard/AdminRefundRequestsPage.tsx</code>.</li><li><strong>What it does:</strong> Lists refund requests with tabs for status (All / Pending / Approved / Rejected). Table shows request details (student, instructor, slot, amount, status, etc.). For pending requests, admin can Approve or Reject (with optional reason). Disabling both buttons while one request is being processed avoids race conditions.</li><li><strong>Frontend – GraphQL:</strong><ul><li>Query: <code>GET_REFUND_REQUESTS</code> (variable <code>status: RefundRequestStatus</code> optional).</li><li>Mutations: <code>APPROVE_REFUND_REQUEST</code> (id), <code>REJECT_REFUND_REQUEST</code> (id, optional rejectionReason).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/admin-dashboard/AdminRefundRequestsPage.tsx</code></li><li><code>Frontend/src/graphql/mutations/refundRequest.ts</code> (<code>GET_REFUND_REQUESTS</code>, <code>APPROVE_REFUND_REQUEST</code>, <code>REJECT_REFUND_REQUEST</code>)</li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> <code>server/src/graphql/resolvers/refundRequest.resolver.js</code> – <code>getRefundRequests</code>, <code>approveRefundRequest</code>, <code>rejectRefundRequest</code>. Business rules (e.g. no refund if lesson past or completed/missed) are enforced in these resolvers.</li><li><strong>TypeDefs:</strong> <code>server/src/graphql/typeDefs/refundRequest.typeDefs.js</code> – <code>RefundRequest</code> type, <code>RefundRequestStatus</code> enum, <code>Query.getRefundRequests(status)</code>, <code>Mutation.approveRefundRequest</code>, <code>Mutation.rejectRefundRequest</code>.</li></ul></li><li><strong>Data flow:</strong> Load → <code>getRefundRequests(status)</code> (or no status for “all”). Tab change → refetch with new status. Approve/Reject → mutation → refetch list.</li></ul><hr><h3 id="_3-9-help-support-super-admin-only" tabindex="-1">3.9 Help &amp; Support (Super admin only) <a class="header-anchor" href="#_3-9-help-support-super-admin-only" aria-label="Permalink to &quot;3.9 Help &amp; Support (Super admin only)&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/admin-dashboard/help-support</code></li><li><strong>Component:</strong> Wrapped in <code>SuperAdminRoute</code>; the actual content is <code>QuestionsAnswers</code> from <code>Frontend/src/pages/private/admin-dashboard/HelpSupport.tsx</code>. It contains two tabs: <strong>FAQ</strong> (FaqTab) and <strong>Contact Details</strong> (ContactDetails).</li><li><strong>What it does:</strong><ul><li><strong>FAQ tab:</strong> List of FAQs for the admin; add/edit/delete FAQs. Uses <code>FaqTab</code> → <code>FaqForm</code>, <code>FaqList</code>; <code>FaqList</code> uses <code>GET_FAQS_BY_ADMIN</code>; create/update/delete use the FAQ mutations.</li><li><strong>Contact details tab:</strong> Manage support contact (e.g. email). Uses <code>GET_MY_CONTACT_DETAIL</code> and <code>CREATE_CONTACT_DETAIL</code> / <code>UPDATE_CONTACT_DETAIL</code>.</li></ul></li><li><strong>Frontend – GraphQL:</strong><ul><li>FAQ: <code>GET_FAQS_BY_ADMIN</code> (adminId), and FAQ create/update/delete mutations (from <code>Frontend/src/graphql/Queries/Faqs.ts</code> and related mutation files).</li><li>Contact: <code>GET_MY_CONTACT_DETAIL</code>, <code>CREATE_CONTACT_DETAIL</code>, <code>UPDATE_CONTACT_DETAIL</code> from <code>Frontend/src/graphql/Queries/AdminContact.ts</code> and <code>Frontend/src/graphql/mutations/AdminContact.ts</code> (or equivalent).</li></ul></li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/admin-dashboard/HelpSupport.tsx</code></li><li><code>Frontend/src/components/AdminComponents/FaqTab.tsx</code>, <code>FaqForm.tsx</code>, <code>FaqList.tsx</code></li><li><code>Frontend/src/components/AdminComponents/ContactDetails.tsx</code></li><li><code>Frontend/src/graphql/Queries/Faqs.ts</code>, <code>Frontend/src/graphql/Queries/AdminContact.ts</code>, and AdminContact mutations</li></ul></li><li><strong>Backend:</strong><ul><li><strong>Resolvers:</strong> FAQ: <code>server/src/graphql/resolvers/Faqs.resolver.js</code> (e.g. getFaqsByAdmin, createFaq, updateFaq, deleteFaq). Contact: <code>server/src/graphql/resolvers/ContactDetail.resolver.js</code> – <code>getMyContactDetail</code>, <code>getAllContactDetails</code>; create/update in same or Contact service.</li><li><strong>TypeDefs:</strong> FAQ types in <code>server/src/graphql/typeDefs/Faq&#39;sTypes.js</code> (or similar). Contact in <code>server/src/graphql/typeDefs/AdminContactTypes.js</code>.</li></ul></li><li><strong>Data flow:</strong> FAQ: load list by admin → add/edit/delete via mutations → refetch. Contact: load current detail → create or update → refetch.</li></ul><hr><h2 id="_4-where-is-it-quick-reference" tabindex="-1">4. “Where is it?” quick reference <a class="header-anchor" href="#_4-where-is-it-quick-reference" aria-label="Permalink to &quot;4. “Where is it?” quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Route</th><th>Main frontend file(s)</th><th>Main GraphQL (frontend)</th><th>Backend resolver / typeDefs</th></tr></thead><tbody><tr><td>Overview / Analytics</td><td><code>/admin-dashboard/overview</code></td><td><code>adminOverview.tsx</code></td><td><code>AdminContact.ts</code>: GET_ADMIN_ANALYTICS, GET_ALL_INSTRUCTORS</td><td>AdminAnalytics.resolver, AdminOverallAnalyticsTypes</td></tr><tr><td>Admin Access</td><td><code>/admin-dashboard/admin-access</code></td><td><code>AdminAccess.tsx</code></td><td><code>auth.ts</code>: GET_ALL_SIGNUP_LINKS, CREATE/DELETE signup link</td><td>SignupLinkResolver, SignupLinkTypedef</td></tr><tr><td>Documents</td><td><code>/admin-dashboard/documentsManagement</code></td><td><code>InstructorDocumentsTable.tsx</code>, <code>DocumentsDetailPage.tsx</code></td><td><code>InstructorProfiles.ts</code>: GET_ALL_INSTRUCTORS (allInstructors)</td><td>resolvers.js (allInstructors), typeDefs.js</td></tr><tr><td>Instructor management</td><td><code>/admin-dashboard/InstructorManagement</code></td><td><code>InstructorManagement.tsx</code> + AdminComponents (Filter, Card, Modals)</td><td><code>InstructorProfiles.ts</code>: GET_ALL_INSTRUCTORS_DETAILS, DELETE_INSTRUCTORS</td><td>resolvers.js: allInstructorsWithDetails, deleteInstructors</td></tr><tr><td>Booking management</td><td><code>/admin-dashboard/bookingManagement</code></td><td><code>StudentBookingTable.tsx</code> (in AdminComponents)</td><td><code>AdminBookingShowcase.ts</code>, <code>AdminBookingsShowcase</code> mutations</td><td>AdminBookingType.resolver, AdminBookingType typeDefs</td></tr><tr><td>Student management</td><td><code>/admin-dashboard/StudentManagement</code></td><td><code>StudentManagement.tsx</code> + AdminComponents</td><td><code>StudentQueries.ts</code>: GET_ALL_STUDENTS_ADMIN, DELETE_STUDENTS</td><td>resolvers.js: allStudentsWithLessonStats, deleteStudents</td></tr><tr><td>Transactions</td><td><code>/admin-dashboard/transactions</code></td><td><code>AdminTransactionsPage.tsx</code></td><td><code>transactionQueries.ts</code>: GET_ADMIN_<em>, GET_PLATFORM_COMMISSION_</em>, UPDATE_*</td><td>transaction.resolver, transaction.typeDefs</td></tr><tr><td>Refund requests</td><td><code>/admin-dashboard/refund-requests</code></td><td><code>AdminRefundRequestsPage.tsx</code></td><td><code>refundRequest.ts</code>: GET_REFUND_REQUESTS, APPROVE/REJECT</td><td>refundRequest.resolver, refundRequest.typeDefs</td></tr><tr><td>Help &amp; Support</td><td><code>/admin-dashboard/help-support</code></td><td><code>HelpSupport.tsx</code>, FaqTab, ContactDetails</td><td>Faqs.ts, AdminContact.ts + mutations</td><td>Faqs.resolver, ContactDetail.resolver, Faq&#39;sTypes, AdminContactTypes</td></tr></tbody></table><hr><h2 id="_5-shared-pieces" tabindex="-1">5. Shared pieces <a class="header-anchor" href="#_5-shared-pieces" aria-label="Permalink to &quot;5. Shared pieces&quot;">​</a></h2><ul><li><strong>Auth:</strong> Admin dashboard relies on the same auth context as the rest of the app (e.g. <code>useAuth()</code> in <code>AdminLayout</code>). Token is sent with every GraphQL request; backend resolvers check <code>user</code> and often require <code>user.role === &#39;Admin&#39;</code> (or similar).</li><li><strong>Socket:</strong> Booking notification count and badge use <code>useBookingNotifications</code> and <code>initSocket</code> in <code>AdminLayout</code>; backend likely emits events when new bookings are created so the admin sees an updated count without refreshing.</li><li><strong>Private route:</strong> <code>AdminPrivateRoute</code> (used in <code>AdminRoutes</code>) ensures only logged-in admins can access any child route; otherwise redirect to sign-in or a default page.</li></ul><hr><p>This completes Phase 1 (Admin Dashboard). For Student Dashboard, Instructor Dashboard, Authentication, and Payments/Stripe, see the other phase documents in this folder (when added) and the <a href="./DEVELOPER_INDEX">DEVELOPER_INDEX.md</a>.</p>',49)])])}const h=t(s,[["render",r]]);export{g as __pageData,h as default};
